examples.template:
MonarchAiGenerativeUi(
    part = MonarchAiUiPart(
        {{component}},
        MonarchAiJSON.Object(
            mapOf(
                "label" to MonarchAiJSON.Text({{props.label}}),
                "value" to MonarchAiJSON.Text({{props.value}}),
                "change" to MonarchAiJSON.Text({{props.change}}),
            ),
        ),
    ),
    registry = registry,
)

examples.setupTemplate:
val registry = remember {
    MonarchAiUiRegistry().apply {
        register(
            {{component}},
            { json ->
                val label = json["label"]?.stringValue
                val value = json["value"]?.stringValue
                if (label != null && value != null) Triple(label, value, json["change"]?.stringValue) else null
            },
        ) { metric, _ ->
            MonarchCard {
                MonarchText(text = metric.first, style = MonarchTextStyle.BodyStrong)
                MonarchText(text = metric.second, style = MonarchTextStyle.Heading)
                metric.third?.let { MonarchBadge(text = it, tone = MonarchTone.Success) }
            }
        }
    }
}

